DATE_FIELDS = ("calendarDate", "date", "startDate", "startTime", "timestamp")


def parse_question(question: str) -> list[str]:
    """Select supported metric categories mentioned in a question."""
    normalized = question.casefold()
    selected = []
    for key, spec in METRICS.items():
        query_terms = spec.query_terms
        if key == "heart_rate" and re.search(r"\bheart rate variability\b", normalized):
            query_terms = ("resting heart", "rhr")
        if any(re.search(rf"\b{re.escape(term)}\b", normalized) for term in query_terms):
            selected.append(key)
    return selected


def _as_date(value: object) -> date | None:
    """Convert a Garmin date-like value to a calendar date."""
    if isinstance(value, datetime):
        return value.date()
    if isinstance(value, date):
        return value
    if isinstance(value, str):
        try:
            return date.fromisoformat(value[:10])
        except ValueError:
            return None
    return None


def _numeric(value: object) -> float | None:
    """Accept finite numeric measurements while excluding booleans."""
    if isinstance(value, bool) or not isinstance(value, (int, float)):
        return None
    numeric_value = float(value)
    return numeric_value if isfinite(numeric_value) else None


def _walk_numeric_fields(
    payload: object,
    inherited_date: date | None = None,
    path: tuple[str, ...] = (),
):
    """Yield dated numeric leaves from nested Garmin JSON records."""
    if isinstance(payload, list):
        for item in payload:
            yield from _walk_numeric_fields(item, inherited_date, path)
        return
    if not isinstance(payload, dict):
        return

    record_date = inherited_date
    for field in DATE_FIELDS:
        if field in payload:
            record_date = _as_date(payload[field]) or record_date
            break

    for key, value in payload.items():
        if key in DATE_FIELDS:
            continue
        numeric_value = _numeric(value)
        child_path = path + (key,)
        if numeric_value is not None:
            yield record_date, child_path, numeric_value
        else:
            yield from _walk_numeric_fields(value, record_date, child_path)


def normalize_payload(payload: object, spec: MetricSpec) -> dict[str, dict[date, float]]:
    """Extract dated measurements whose field names match a metric specification."""
    field_names = {field.casefold(): field for field in spec.fields}
    values: dict[str, dict[date, list[float]]] = defaultdict(lambda: defaultdict(list))

    for record_date, path, value in _walk_numeric_fields(payload):
        if record_date is None or not path:
            continue
        path_names = (".".join(path[start_index:]).casefold() for start_index in range(len(path)))
        field_name = next((field_names[name] for name in path_names if name in field_names), None)
        if field_name:
            values[field_name][record_date].append(value)

    return {
        field: {record_date: mean(daily_values) for record_date, daily_values in daily.items()}
        for field, daily in values.items()
    }


def _select_series(
    series_by_field: dict[str, dict[date, float]],
    spec: MetricSpec,
) -> tuple[str, dict[date, float]] | None:
    """Choose the best-supported field using the metric's explicit priority order."""
    if not series_by_field:
        return None
    normalized = {field.casefold(): values for field, values in series_by_field.items()}
    for preferred in spec.preferred_fields:
        if preferred.casefold() in normalized:
            return preferred, normalized[preferred.casefold()]
    field = max(series_by_field, key=lambda name: len(series_by_field[name]))
    return field, series_by_field[field]


def _format_value(value: float, field: str, spec: MetricSpec) -> tuple[float, str]:
    """Convert recognized duration fields to hours and return a display unit."""
    if field.casefold().endswith("seconds"):
        return value / 3600, "hours"
    if spec.label == "Sleep" and "score" in field.casefold():
        return value, "score"
    return value, spec.unit


def format_trend(
    key: str,
    series_by_field: dict[str, dict[date, float]],
    start_date: date,
    end_date: date,
) -> str:
    """Summarize a selected metric with its date range and evidence count."""
    spec = METRICS[key]
    selected = _select_series(series_by_field, spec)
    title = f"{spec.label} | {start_date} to {end_date}"
    if selected is None:
        fields = ", ".join(spec.fields)
        return f"{title}\nNo dated readings matched expected fields: {fields}."

    field, values_by_date = selected
    readings = sorted(values_by_date.items())
    values = [value for _, value in readings]
    latest_date, latest_value = readings[-1]
    latest_display, unit = _format_value(latest_value, field, spec)
    median_display, _ = _format_value(median(values), field, spec)
    minimum_display, _ = _format_value(min(values), field, spec)
    maximum_display, _ = _format_value(max(values), field, spec)
    lines = [
        title,
        f"Evidence: {len(values)} dated readings of {field}",
        f"Latest: {latest_display:.1f} {unit} on {latest_date}",
        f"Median: {median_display:.1f} {unit}",
        f"Range: {minimum_display:.1f}-{maximum_display:.1f} {unit}",
    ]

    recent = values[-7:]
    recent_average, _ = _format_value(mean(recent), field, spec)
    lines.append(f"Latest {len(recent)} readings average: {recent_average:.1f} {unit}")
    if len(values) >= 14:
        previous_average = mean(values[-14:-7])
        previous_display, _ = _format_value(previous_average, field, spec)
        difference, _ = _format_value(mean(recent) - previous_average, field, spec)
        lines.append(f"Previous 7 readings average: {previous_display:.1f} {unit}")
        lines.append(f"Difference: {difference:+.1f} {unit}")
    lines.append("Descriptive only; this does not diagnose a condition or establish cause.")
    return "\n".join(lines)


def pearson_correlation(left: list[float], right: list[float]) -> float | None:
    """Return Pearson correlation, or None when samples cannot define it."""
    if len(left) != len(right) or len(left) < 2:
        return None
    left_mean = mean(left)
    right_mean = mean(right)
    left_delta = [value - left_mean for value in left]
    right_delta = [value - right_mean for value in right]
    denominator = sqrt(sum(value**2 for value in left_delta) * sum(value**2 for value in right_delta))
    if denominator == 0:
        return None
    return sum(a * b for a, b in zip(left_delta, right_delta)) / denominator


def format_associations(
    selected_metrics: list[str],
    datasets: dict[str, dict[str, dict[date, float]]],
    start_date: date,
    end_date: date,
) -> str:
    """Report same-day associations without implying that one metric causes another."""
    lines = [f"Same-day associations | {start_date} to {end_date}"]
    for left_key, right_key in combinations(selected_metrics, 2):
        left_spec = METRICS[left_key]
        right_spec = METRICS[right_key]
        left_selected = _select_series(datasets.get(left_key, {}), left_spec)
        right_selected = _select_series(datasets.get(right_key, {}), right_spec)
        if left_selected is None or right_selected is None:
            lines.append(f"{left_spec.label} vs {right_spec.label}: insufficient matching fields.")
            continue

        left_field, left_values = left_selected
        right_field, right_values = right_selected
        shared_dates = sorted(left_values.keys() & right_values.keys())
        if len(shared_dates) < 14:
            lines.append(
                f"{left_spec.label} vs {right_spec.label}: only {len(shared_dates)} same-day readings; need 14."
            )
            continue

        correlation = pearson_correlation(
            [left_values[day] for day in shared_dates],
            [right_values[day] for day in shared_dates],
        )
        if correlation is None:
            lines.append(f"{left_spec.label} vs {right_spec.label}: readings do not vary enough to compare.")
            continue
        lines.append(
            f"{left_spec.label} ({left_field}) vs {right_spec.label} ({right_field}): "
            f"r={correlation:+.2f} across {len(shared_dates)} same-day readings."
        )

    lines.append("Associations are descriptive and do not show that one measurement causes another.")
    return "\n".join(lines)


def _load_api_key() -> str | None:
    """Load the Personal API key from the project .env or process environment."""
    load_dotenv(Path(__file__).resolve().with_name(".env"))
    return os.getenv("GARMIN_PERSONAL_API_KEY") or os.getenv("GARMIN_API_KEY")


def _fetch_datasets(
    client: GarminPersonalApiClient,
    selected_metrics: list[str],
    start_date: date,
    end_date: date,
    raw_payloads: dict[str, object] | None = None,
) -> tuple[dict[str, dict[str, dict[date, float]]], dict[str, str]]:
    """Fetch only requested metric ranges and normalize successful responses."""
    datasets = {}
    failures = {}
    payloads_by_method = {}
    failures_by_method = {}
    for key in selected_metrics:
        spec = METRICS[key]
        if spec.method in failures_by_method:
            failures[key] = failures_by_method[spec.method]
            continue
        try:
            if spec.method not in payloads_by_method:
                payloads_by_method[spec.method] = getattr(client, spec.method)(start_date, end_date)
        except Exception as error:
            failures_by_method[spec.method] = type(error).__name__
            failures[key] = failures_by_method[spec.method]
            continue
        payload = payloads_by_method[spec.method]
        if raw_payloads is not None:
            raw_payloads[key] = payload
        datasets[key] = normalize_payload(payload, spec)
    return datasets, failures


def main() -> int:
    """Answer a supported Garmin health question using local calculations."""
    parser = argparse.ArgumentParser(description="Ask a private, local Garmin health-data question.")
    parser.add_argument("question", nargs="+", help="question mentioning HRV, sleep, stress, steps, battery, or heart rate")
    parser.add_argument("--days", type=int, default=30, help="calendar days to query (default: 30)")
    args = parser.parse_args()
    if args.days < 1:
        parser.error("--days must be at least 1")

    question = " ".join(args.question)
    selected_metrics = parse_question(question)
    if not selected_metrics:
        print("Name a supported metric: HRV, sleep, stress, steps, Body Battery, or heart rate.")
        print("No Garmin data was requested.")
        return 0

    api_key = _load_api_key()
    if not api_key:
        print("Set GARMIN_PERSONAL_API_KEY in .env (or in your environment).", file=sys.stderr)
        return 1

    end_date = date.today()
    start_date = end_date - timedelta(days=args.days - 1)
    try:
        with PersonalApiAuthenticator() as authenticator:
            token = authenticator.obtain_token(api_key)
        with GarminPersonalApiClient(token.access_token) as client:
            datasets, failures = _fetch_datasets(client, selected_metrics, start_date, end_date)
    except Exception as error:
        print(f"Could not connect to Garmin ({type(error).__name__}).", file=sys.stderr)
        return 1

    comparison_terms = ("compare", "correlat", "relationship", "together", "coincide")
    if len(selected_metrics) > 1 and any(term in question.casefold() for term in comparison_terms):
        print(format_associations(selected_metrics, datasets, start_date, end_date))
    else:
        for index, key in enumerate(selected_metrics):
            if index:
                print()
            print(format_trend(key, datasets.get(key, {}), start_date, end_date))

    if failures:
        failed_labels = ", ".join(METRICS[key].label for key in failures)
        print(f"\nSome data sources were unavailable: {failed_labels}.", file=sys.stderr)
    return 0


if __name__ == "__main__":
    raise SystemExit(main())